return ['domain'=>'publishpress-authorsn%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','plural-forms'=>'nplurals=3; plural=(n % 10 == 1 && n % 100 != 11 ? 0 : n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 10 || n % 100 >= 20) ? 1 : 2);','language'=>'ru_RU','project-id-version'=>'PublishPress Authors 4.20.0','pot-creation-date'=>'2026-11-12T07:29:08+00:00','po-revision-date'=>'2026-11-12 10:33+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['PublishPress Authors'=>'PublishPress Authors','https://wordpress.org/plugins/publishpress-authors/'=>'https://wordpress.org/plugins/publishpress-authors/','PublishPress Authors allows you to add multiple authors and guest authors to WordPress posts'=>'PublishPress Authors позволяет добавлять несколько авторов и гостевых авторов к записям WordPress','PublishPress'=>'PublishPress','https://publishpress.com'=>'https://publishpress.com','Upgrade to Pro'=>'Обновить до Pro','This plugin can be deleted.'=>'Этот плагин может быть удалён.','Actions provided by PublishPress plugins.'=>'Действия, предоставляемые плагинами PublishPress.','List Authors'=>'Список авторов','Lists PublishPress Authors. Results never include author email addresses.'=>'Список авторов PublishPress. Результаты никогда не включают адреса электронной почты авторов.','Get Author'=>'Получить автора','Gets one PublishPress Author by term ID. The response never includes an email address.'=>'Получает одного автора PublishPress по ID термина. Ответ никогда не включает адрес электронной почты.','Get Post Authors'=>'Получить авторов записи','Gets the ordered PublishPress Authors assigned to one editable post. The response never includes author email addresses.'=>'Получает упорядоченных авторов PublishPress, назначенных одной редактируемой записи. Ответ никогда не включает адреса электронной почты авторов.','Get Author Fields'=>'Получить поля автора','Lists enabled author-profile field definitions without exposing profile values.'=>'Список определений полей профиля авторов, без раскрытия значений профиля.','Author not found.'=>'Автор не найден.','Post not found.'=>'Запись не найдена.','Authors List'=>'Список авторов','Display authors list.'=>'Отобразить список авторов.','Title'=>'Название','Layout'=>'Макет','Display All Authors (including those who have not written any posts)'=>'Отобразить всех авторов (включая тех, кто не написал ни одной записи)','Enable author\'s search box'=>'Включить поле поиска автора','Limits per page'=>'Ограничения на странице','Authors'=>'Авторы','Order'=>'Порядок','Order by'=>'Сортировать по','Grid Columns'=>'Столбцы сетки','Author\'s search box field (Seperate multiple fields by comma(\',\'))'=>'Поле поиска автора (разделяйте несколько полей запятой (\',\'))','All Authors'=>'Все авторы','Guest Authors'=>'Гостевые авторы','Users Authors'=>'Авторы пользователей','Ascending'=>'По возрастанию','Descending'=>'По убыванию','Name'=>'Имя','Post Counts'=>'Количество записей','First Name'=>'Имя','Last Name'=>'Фамилия','Showing authors starting with %s'=>'Показать авторов, начинающихся на %s','Showing all authors'=>'Показ всех авторов','No authors found.'=>'Авторы не найдены.','Loading authors...'=>'Загрузка авторов...','Unable to load authors.'=>'Не удалось загрузить авторов.','Default Search'=>'Поиск по умолчанию','Search Box'=>'Поисковая строка','Search'=>'Поиск','Search authors'=>'Поиск авторов','Search authors by'=>'Поиск авторов по','No recent posts from this author'=>'Нет недавних записей от этого автора','Request status.'=>'Статус запроса.','Security error. Kindly reload this page and try again'=>'Ошибка безопасности. Пожалуйста, перезагрузите эту страницу и попробуйте снова','You cannot edit an author profile linked to an administrator account.'=>'Вы не можете редактировать профиль автора, связанный с учетной записью администратора.','You do not have permission to edit this author profile because it is linked to a user account you do not have permission to edit.'=>'У вас нет разрешения на редактирование этого профиля автора, так как он связан с учетной записью пользователя, которую вы не можете редактировать.','Sorry, this WordPress user is already mapped to another Author. By default, each user can only be connected to one Author profile.'=>'Извините, этот пользователь WordPress уже сопоставлен с другим автором. По умолчанию каждый пользователь может быть связан только с одним профилем автора.','Registered User is required.'=>'Требуется зарегистрированный пользователь.','Author URL cannot be empty.'=>'URL автора не может быть пустым.','Another user with Author URL already exists.'=>'Другой пользователь с таким URL автора уже существует.','Author name is required'=>'Имя автора обязательно','No post ID provided for Authors_Iterator constructor. Are you not in a loop or is $post not set?'=>'Не указан ID записи для конструктора Authors_Iterator. Вы не в цикле или $post не установлен?','Display name publicly as'=>'Отображаемое имя публично как','Email'=>'Электронная почта','Author Type'=>'Тип автора','Guest Author With User Account'=>'Гостевой автор с учетной записью пользователя','Registered Author With User Account'=>'Зарегистрированный автор с учетной записью пользователя','Guest Author With No User Account'=>'Гостевой автор без учетной записи пользователя','Edit User'=>'Редактировать пользователя','Edit Author Profile'=>'Редактировать профиль автора','Create Author Profile'=>'Создать профиль автора','General'=>'Общее','Avatar'=>'Аватар','Author'=>'Автор','Registered User'=>'Зарегистрированный пользователь','Biographical Info'=>'Биографическая информация','Avatar Source'=>'Источник аватара','Default Avatar'=>'Аватар по умолчанию','(Uses the %1$s Email field %2$s to find the Gravatar account if default avatar is not uploaded in Authors Settings)'=>'(Использует поле %1$s Email %2$s для поиска аккаунта Gravatar, если аватар по умолчанию не загружен в настройках авторов)','Custom image'=>'Пользовательское изображение','Alternative Text'=>'Альтернативный текст','Describe the avatar. Leave blank to use the Media Library alternative text or author name.'=>'Опишите аватар. Оставьте пустым, чтобы использовать альтернативный текст из медиатеки или имя автора.','Decorative Image'=>'Декоративное изображение','Use empty alternative text when this avatar is decorative.'=>'Используйте пустой альтернативный текст, когда этот аватар является декоративным.','Website'=>'Сайт','Author Category'=>'Категория автора','Select the default Category for this Author. This will be used when the Author is added to new posts.'=>'Выберите категорию по умолчанию для этого автора. Она будет использоваться, когда автор добавляется в новые записи.','Do not show this profile publicly'=>'Не показывать этот профиль публично','(required)'=>'(обязательно)','Select image'=>'Выбрать изображение','Remove this image'=>'Удалить это изображение','Select a user'=>'Выбрать пользователя','Author email error'=>'Ошибка электронной почты автора','Create an author profile for a current user account. You can select users who are allowed to edit posts. This user will be able to update their profile.'=>'Создайте профиль автора для текущей учетной записи пользователя. Вы можете выбрать пользователей, которым разрешено редактировать записи. Этот пользователь сможет обновить свой профиль.','Create an author profile and a linked user account. This account will be in the "Guest Author" role and will not be able to login to the WordPress dashboard or update their profile.'=>'Создайте профиль автора и связанную учетную запись пользователя. Эта учетная запись будет в роли "Автор-гость" и не сможет войти в панель управления WordPress или обновить свой профиль.','Create an author profile with no linked user account. This option is lightweight but may have compatibility issues with other themes and plugins.'=>'Создайте профиль автора без связанной учетной записи пользователя. Этот вариант легковесный, но может иметь проблемы совместимости с другими темами и плагинами.','Author Email'=>'Электронная почта автора','User Account'=>'Учетная запись пользователя','Sync author and user fields'=>'Синхронизировать поля автора и пользователя','Convert to Guest Author With User Account'=>'Конвертировать в автора-гостя с учетной записью пользователя','Update post count'=>'Обновить количество записей','No authors were updated'=>'Авторы не были обновлены','Updated %d authors'=>'Обновлено %d авторов','An author with the name provided already exists.'=>'Автор с указанным именем уже существует.','An author email is required when creating new User Author.'=>'Электронная почта автора обязательна при создании нового автора-пользователя.','This email address is already linked to another WordPress user.'=>'Этот адрес электронной почты уже связан с другим пользователем WordPress.','Now inspecting or updating %d total authors'=>'Теперь проверяется или обновляется %d всего авторов','%1$d/%2$d: Inspecting the user %3$d'=>'%1$d/%2$d: Проверка пользователя %3$d','All is set. No author need to be updated'=>'Все готово. Авторы не нуждаются в обновлении','Now inspecting or updating %d total posts'=>'Теперь проверяется или обновляется %d всего записей','%1$d/%2$d: Inspecting the post %3$d'=>'%1$d/%2$d: Проверка записи %3$d','Creating author term for the user %d'=>'Создание термина автора для пользователя %d','Adding the author term %1$d to the post %2$d'=>'Добавление термина автора %1$d к записи %2$d','All is set. No posts need to be updated'=>'Все готово. Записи не нуждаются в обновлении','Configure'=>'Настроить','Please correct your form errors below and try again.'=>'Пожалуйста, исправьте ошибки в вашей форме ниже и попробуйте снова.','Cheatin&#8217; uh?'=>'Обманываешь, а?','You do not have necessary permissions to complete this action.'=>'У вас нет необходимых прав для выполнения этого действия.','Post does not exist'=>'Запись не существует','No author term'=>'Нет термина автора','"post_author" is empty'=>'"post_author" пусто','Drag-and-drop Authors to add them to the %s category'=>'Перетащите авторов, чтобы добавить их в категорию %s','Search for an author'=>'Поиск автора','This option is showing because you do not have a WordPress user selected as an author. For some tasks, it can be helpful to have a user selected here. This user will not be visible on the front of your site.'=>'Эта опция отображается, потому что у вас не выбран пользователь WordPress в качестве автора. Для некоторых задач может быть полезно выбрать здесь пользователя. Этот пользователь не будет виден на фронте вашего сайта.','Search for an user'=>'Поиск пользователя','Author Box'=>'Бокс автора','Default Author Box'=>'Стандартный бокс автора','Hide Author Box'=>'Скрыть бокс автора','Filter posts by author'=>'Фильтровать посты по автору','Remove %s'=>'Удалить %s','New author added.'=>'Новый автор добавлен.','Author profile deleted.'=>'Профиль автора удалён.','Author profile updated.'=>'Профиль автора обновлён.','Error adding author account.'=>'Ошибка при добавлении аккаунта автора.','Error updating author profile.'=>'Ошибка при обновлении профиля автора.','Authors deleted.'=>'Авторы удалены.','Author URL'=>'URL автора','Co-Authors Plus must be installed and active.'=>'Co-Authors Plus должен быть установлен и активен.','Read more.'=>'Читать далее.','The results could not be loaded.'=>'Результаты не могут быть загружены.','Please delete %d character'=>'Пожалуйста, удалите %d символ','Please delete %d characters'=>'Пожалуйста, удалите %d символа','Please enter %d or more character'=>'Пожалуйста, введите %d или более символ','Please enter %d or more characters'=>'Пожалуйста, введите %d или более символов','Loading more results...'=>'Загрузка дополнительных результатов...','You can only select %d item'=>'Вы можете выбрать только %d элемент','You can only select %d items'=>'Вы можете выбрать только %d элемента','No results found'=>'Результаты не найдены','Searching...'=>'Поиск...','Remove all items'=>'Удалить все элементы','No results match'=>'Нет совпадающих результатов','Need PublishPress Authors Support?'=>'Нужна поддержка PublishPress Authors?','If you need help or have a new feature request, let us know.'=>'Если вам нужна помощь или у вас есть запрос на новую функцию, дайте нам знать.','Request Support'=>'Запросить поддержку','Detailed documentation is also available on the plugin website.'=>'Подробная документация также доступна на сайте плагина.','View Knowledge Base'=>'Просмотреть базу знаний','Text'=>'Текст','Multiline text'=>'Многострочный текст','WYSIWYG Editor'=>'WYSIWYG редактор','Link'=>'Ссылка','Email address'=>'Адрес электронной почты','Active'=>'Активный','Disabled'=>'Отключено','Optional'=>'Необязательно','Required'=>'Обязательно','No'=>'Нет','Yes, this is a Social Profile'=>'Да, это социальный профиль','Select an option'=>'Выберите вариант','dofollow'=>'dofollow','nofollow'=>'nofollow','Discover authors, categories and boxes for a post byline'=>'Откройте авторов, категории и блоки для подписи поста','Read paginated existing author term IDs and enabled author categories plus native Author Box choices for one editable post. Uses byline permissions rather than granting profile management. Never creates profiles for unassigned WordPress users. Follow each list total_pages separately.'=>'Читать идентификаторы существующих авторов с пагинацией и включенные категории авторов, а также выборы нативного блока автора для одного редактируемого поста. Использует разрешения подписи, а не предоставляет управление профилем. Никогда не создает профили для не назначенных пользователей WordPress. Следите за каждым списком total_pages отдельно.','Read post authors and Author Box'=>'Читать авторов поста и блок автора','Read exact ordered author term IDs, author-category assignments, fallback WordPress author and per-post Author Box with a revision hash. Requires native byline and edit_post permissions; never guesses author IDs or writes during reads.'=>'Читать точные упорядоченные идентификаторы авторов, присвоения авторов-категорий, запасного автора WordPress и блок автора на пост с хешом ревизии. Требует нативных разрешений подписи и edit_post; никогда не угадывает идентификаторы авторов или записывает во время чтения.','Update post authors and Author Box'=>'Обновить авторов поста и блок автора','Replace a post byline with ordered author_ids, or patch category assignments and its Author Box. Omitted fields are preserved. Requires the latest hash and an enabled post type. dry_run previews without saving. Discover authors, categories and native layout choices first.'=>'Заменить подпись поста на упорядоченные author_ids или исправить присвоения категорий и его блок автора. Пропущенные поля сохраняются. Требует последнего хеша и включенного типа поста. dry_run предварительно просматривает без сохранения. Сначала откройте авторов, категории и нативные варианты оформления.','Update bylines on multiple posts'=>'Обновить подписи на нескольких постах','Apply explicit per-post byline changes after validating every object, revision hash and author/category identifier. Each change has its own post_id and expected_hash. dry_run previews all targets without saving. On failure, prior writes are compensated with their original bylines.'=>'Примените явные изменения подписи на посте после проверки каждого объекта, хеша ревизии и идентификатора автора/категории. Каждое изменение имеет свой собственный post_id и expected_hash. dry_run предварительно просматривает все цели без сохранения. В случае неудачи предыдущие записи компенсируются их оригинальными подписями.','Choose a post type enabled for Authors.'=>'Выберите тип поста, включенный для авторов.','The post byline changed. Read it again before saving.'=>'Подпись поста изменена. Прочитайте ее снова перед сохранением.','Choose existing author term IDs.'=>'Выберите существующие идентификаторы авторов.','Empty bylines must first be enabled in Authors settings.'=>'Пустые подписи должны быть сначала включены в настройках авторов.','Category assignments must refer to the selected authors.'=>'Присвоения категорий должны ссылаться на выбранных авторов.','Multiple author categories are disabled.'=>'Несколько категорий авторов отключены.','Choose an enabled author category available for this post type.'=>'Выберите включенную категорию автора, доступную для этого типа поста.','An empty byline preserves its existing fallback WordPress author.'=>'Пустая подпись сохраняет своего существующего запасного автора WordPress.','Choose an existing fallback WordPress user.'=>'Выберите существующего запасного пользователя WordPress.','Choose an available Author Box and enable per-post box selection.'=>'Выберите доступный блок автора и включите выбор блока для каждого поста.','The byline save failed and its original state could not be restored. Read the post before retrying.'=>'Сохранение подписи не удалось, и восстановить ее оригинальное состояние не удалось. Прочитайте пост перед повторной попыткой.','Could not save the complete post byline.'=>'Не удалось сохранить полную подпись поста.','Include each post only once in a batch.'=>'Включите каждый пост только один раз в пакет.','The batch failed and some original bylines could not be restored. Read all target posts before retrying.'=>'Пакет не удался, и некоторые оригинальные подписи не удалось восстановить. Прочитайте все целевые посты перед повторной попыткой.','List Author Categories'=>'Список категорий авторов','Read native author category IDs, singular/plural names, order, enabled state and schema settings. These group a post byline and differ from post categories. Pro adds per-post-type targeting. Results are paginated.'=>'Читать нативные идентификаторы категорий авторов, единственные/множественные названия, порядок, состояние включения и настройки схемы. Эти группы формируют подпись поста и отличаются от категорий постов. Pro добавляет таргетинг по типу поста. Результаты пагинированы.','Discover Author Category fields'=>'Откройте поля категории автора','Read category identifiers, label and grouping settings, and active-edition targeting choices. Categories describe author byline roles such as Writer or Reviewer, not WordPress post categories.'=>'Читать идентификаторы категорий, метки и настройки группировки, а также активные варианты таргетинга. Категории описывают роли подписи автора, такие как писатель или рецензент, а не категории постов WordPress.','Read Author Category'=>'Читать категорию автора','Read one verified native author category and revision hash. Use this hash when updating or deleting.'=>'Читать одну проверенную нативную категорию автора и хеш ревизии. Используйте этот хеш при обновлении или удалении.','Create or update Author Category'=>'Создать или обновить категорию автора','Create a category with category_name and plural_name or patch an existing ID using expected_hash. Preserves omitted fields, validates post types and requires Pro for post-type targeting. dry_run previews without saving. Category order is an integer position.'=>'Создайте категорию с category_name и plural_name или исправьте существующий ID, используя expected_hash. Сохраняет пропущенные поля, проверяет типы постов и требует Pro для таргетинга по типу поста. dry_run предварительно просматривает без сохранения. Порядок категории - это целое число.','Delete unused Author Category'=>'Удалить неиспользуемую категорию автора','Delete an unused native category and its metadata. Existing post category relationships or author-profile defaults must be reassigned first. Requires expected_hash; dry_run checks without deleting.'=>'Удалить неиспользуемую нативную категорию и ее метаданные. Существующие отношения категорий постов или значения по умолчанию профиля автора должны быть переназначены сначала. Требует expected_hash; dry_run проверяет без удаления.','Singular name'=>'Единственное имя','Plural name'=>'Множественное имя','Schema property'=>'Свойство схемы','Author Category not found.'=>'Категория автора не найдена.','The category changed. Read it again before saving.'=>'Категория изменилась. Прочитайте ее снова перед сохранением.','Use exact category field types from discovery.'=>'Используйте точные типы полей категории из обнаружения.','Singular and plural category names are required.'=>'Требуются единственные и множественные имена категорий.','Category post-type targeting requires Authors Pro.'=>'Целевое назначение типа поста категории требует Authors Pro.','Choose registered post types.'=>'Выберите зарегистрированные типы постов.','An Author Category with this slug already exists.'=>'Категория автора с этим слагом уже существует.','Could not save the native Author Category.'=>'Не удалось сохранить родную категорию автора.','The category save failed; the original state was restored.'=>'Сохранение категории не удалось; оригинальное состояние было восстановлено.','The category save failed and restoration was incomplete. Read it before retrying.'=>'Сохранение категории не удалось, и восстановление было неполным. Прочитайте это перед повторной попыткой.','The category changed. Read it again before deleting.'=>'Категория изменилась. Прочитайте ее снова перед удалением.','Reassign category references before deleting.'=>'Переназначьте ссылки на категории перед удалением.','The category could not be deleted.'=>'Категорию не удалось удалить.','Use the exact native field type shown in discovery.'=>'Используйте точный родной тип поля, показанный в обнаружении.','Choose a list of values from field discovery.'=>'Выберите список значений из обнаружения полей.','Field choice lists require string values from discovery.'=>'Списки выбора полей требуют строковых значений из обнаружения.','Box shortcodes require parallel lists of shortcode and position strings.'=>'Коды коротких записей для блоков требуют параллельные списки строк кода и позиции.','Box shortcodes require string values.'=>'Коды коротких записей для блоков требуют строковых значений.','Each box shortcode needs one matching position.'=>'Каждый код короткой записи блока нуждается в одной соответствующей позиции.','The native field sanitizer is unavailable.'=>'Санитария родного поля недоступна.','List saved Author Lists'=>'Список сохраненных авторов','Read a bounded page of saved Author List presets. Each preset has its own ID and shortcode. This is configuration, not a list of author profiles. Includes native active/trash status.'=>'Прочитайте ограниченную страницу сохраненных предустановок списка авторов. Каждая предустановка имеет свой собственный ID и код короткой записи. Это конфигурация, а не список профилей авторов. Включает родной активный/удаленный статус.','Read saved Author List'=>'Прочитайте сохраненный список авторов','Read one verified list preset, its shortcode and revision hash. Editing a list does not change author profiles, post bylines or Author Boxes.'=>'Прочитайте одну проверенную предустановку списка, ее код короткой записи и хэш ревизии. Редактирование списка не изменяет профили авторов, подписи постов или блоки авторов.','Discover Author List fields'=>'Обнаружить поля списка авторов','Read native layout, display-field, grouping, image, filter and active-edition search/pagination choices. Pro-only controls appear only with Pro active; promotional controls are excluded.'=>'Прочитайте родной макет, поле отображения, группировку, изображение, фильтры и активные варианты поиска/пагинации. Управления только для Pro появляются только с активным Pro; рекламные управления исключены.','Create or update Author List'=>'Создать или обновить список авторов','Create a list with native title and layout fields, or patch a verified preset using its latest hash. Generates a native publishpress_authors_list shortcode from validated fields. Preserves omitted fields and other lists. Use status active to restore a trashed preset. dry_run previews without saving.'=>'Создайте список с родными полями заголовка и макета, или исправьте проверенную предустановку, используя ее последний хэш. Генерирует родной код короткой записи publishpress_authors_list из проверенных полей. Сохраняет пропущенные поля и другие списки. Используйте статус активен для восстановления удаленной предустановки. dry_run предварительно просматривает без сохранения.','Trash or delete Author List'=>'Удалить или удалить список авторов','Trash a verified saved list, or explicitly use permanent true to remove its preset. Requires the latest hash. Does not delete posts or author profiles. dry_run checks without saving.'=>'Удалите проверенный сохраненный список или явно используйте permanent true, чтобы удалить его предустановку. Требуется последний хэш. Не удаляет посты или профили авторов. dry_run проверяет без сохранения.','Author List not found.'=>'Список авторов не найден.','The Author List changed. Read it again before saving.'=>'Список авторов изменился. Прочитайте его снова перед сохранением.','An Author List requires a title and native layout.'=>'Список авторов требует заголовка и родного макета.','The Author List changed. Read it again before deleting.'=>'Список авторов изменился. Прочитайте его снова перед удалением.','List Author Boxes'=>'Список блоков авторов','Read Author Box'=>'Прочитайте блок автора','Discover Author Box fields'=>'Обнаружить поля блока автора','Save Author Box'=>'Сохранить Author Box','Trash Author Box'=>'Удалить Author Box','List author field definitions'=>'Список определений полей автора','Read author field definition'=>'Читать определение поля автора','Discover custom field options'=>'Обнаружить параметры custom field','Save author field definition'=>'Сохранить определение поля автора','Trash author field definition'=>'Удалить определение поля автора','New boxes only: choose a native Free or Pro template from field discovery.'=>'Только новые боксы: выберите родной шаблон Free или Pro из обнаруженных полей.','List a bounded page of native objects with IDs, titles, slugs and status. Only editable objects are returned. Read the exact object and its field schema before editing. Follow total_pages even if permissions filter a page to empty.'=>'Список ограниченной страницы родных объектов с ID, заголовками, слагами и статусом. Возвращаются только редактируемые объекты. Читайте точный объект и его схему полей перед редактированием. Следуйте total_pages, даже если разрешения фильтруют страницу до пустой.','Read a verified native object with its editable settings and revision hash. Does not expose arbitrary post metadata. Custom field definitions are distinct from author profile values.'=>'Читать проверенный родной объект с его редактируемыми настройками и хешем ревизии. Не раскрывает произвольные метаданные поста. Определения полей custom field отличаются от значений профиля автора.','Discover native editor labels, field types, supported choices and edition-specific fields. Optional id selects an existing object. Unknown or inactive-edition fields are rejected during saves.'=>'Обнаружить метки редактора, типы полей, поддерживаемые варианты и поля, специфичные для редакции. Необязательный id выбирает существующий объект. Неизвестные или неактивные поля редакции отклоняются при сохранении.','Create a native object or patch a verified ID using discovered typed fields. New objects need a title and default to draft. Updates require expected_hash, preserve omitted fields and use native sanitizers. dry_run validates without saving. menu_order controls native list ordering. Managing custom field definitions requires Pro.'=>'Создать родной объект или обновить проверенный ID, используя обнаруженные типизированные поля. Новым объектам требуется заголовок и по умолчанию создаются как черновик. Обновления требуют expected_hash, сохранять пропущенные поля и использовать родные очистители. dry_run проверяет без сохранения. menu_order управляет порядком списка родных объектов. Управление определениями полей custom field требует Pro.','Trash a verified native object with delete_post permission and expected_hash. Does not permanently delete it when Trash is disabled. Existing references are not rewritten. dry_run checks without deleting; custom field deletion requires Pro.'=>'Удалить проверенный родной объект с разрешением delete_post и expected_hash. Не удаляет его навсегда, когда Удаление отключено. Существующие ссылки не переписываются. dry_run проверяет без удаления; удаление полей custom field требует Pro.','Field Type'=>'Тип поля','Field Status'=>'Статус поля','Required or optional'=>'Обязательное или необязательное','Social Profile'=>'Социальный профиль','Link relationship'=>'Связь ссылки','Open link in a new tab'=>'Открыть ссылку в новой вкладке','Show in REST API'=>'Показать в REST API','Description'=>'Описание','Native object not found.'=>'Родной объект не найден.','This object changed. Read it again before editing.'=>'Этот объект изменился. Прочитайте его снова перед редактированием.','A title is required for a new object.'=>'Заголовок обязателен для нового объекта.','You cannot create or publish this native object.'=>'Вы не можете создать или опубликовать этот родной объект.','This field name is reserved for account identity or security.'=>'Это имя поля зарезервировано для идентичности аккаунта или безопасности.','Choose a unique author field slug.'=>'Выберите уникальный слаг поля автора.','Choose discovered profile field names for the box order.'=>'Выберите обнаруженные имена полей профиля для порядка боксов.','Choose a discovered template when creating a new Author Box.'=>'Выберите обнаруженный шаблон при создании нового Author Box.','The field order could not be saved. Read the object before retrying.'=>'Порядок полей не удалось сохранить. Прочитайте объект перед повторной попыткой.','Native metadata save failed; the original object was restored.'=>'Сохранение родных метаданных не удалось; оригинальный объект был восстановлен.','Native metadata save failed and the original object could not be fully restored. Read it before retrying.'=>'Сохранение родных метаданных не удалось, и оригинальный объект не может быть полностью восстановлен. Прочитайте его перед повторной попыткой.','This object changed. Read it again before deleting.'=>'Этот объект изменился. Прочитайте его снова перед удалением.','You cannot trash this object, or Trash is disabled.'=>'Вы не можете удалить этот объект, или Удаление отключено.','The native object could not be trashed.'=>'Родной объект не удалось удалить.','Discover author profile fields'=>'Обнаружить поля профиля автора','Read native field labels, types and choices for an author. Enabled custom fields are included. Email, account identity, passwords and privileged user fields are excluded from profile fields; account linking has a separate action.'=>'Читать метки полей, типы и варианты для автора. Включены активные поля custom field. Электронная почта, идентичность аккаунта, пароли и привилегированные пользовательские поля исключены из полей профиля; связывание аккаунтов имеет отдельное действие.','Read author profile details'=>'Читать детали профиля автора','Read an author profile, public native field values and a revision hash. Hidden REST fields, emails and arbitrary metadata are excluded. Use get-profile-fields before editing and the latest hash to update.'=>'Читать профиль автора, публичные значения родных полей и хеш ревизии. Скрытые поля REST, электронные почты и произвольные метаданные исключены. Используйте get-profile-fields перед редактированием и последний хеш для обновления.','Create or update author profile'=>'Создать или обновить профиль автора','Create a guest author, create a profile linked to an existing user_id, or patch an existing profile. Guest creation must be enabled. Discover native fields first; update requires expected_hash. Preserves omitted fields and respects linked-user permissions and administrator profile locks. dry_run validates without saving. Does not create WordPress accounts.'=>'Создайте гостевого автора, создайте профиль, связанный с существующим user_id, или обновите существующий профиль. Создание гостя должно быть включено. Сначала откройте нативные поля; обновление требует expected_hash. Сохраняет пропущенные поля и уважает разрешения связанного пользователя и блокировки профиля администратора. dry_run проверяет без сохранения. Не создает учетные записи WordPress.','Link or unlink an author user account'=>'Связать или разъединить учетную запись автора','Link an existing author to an existing WordPress user, or use user_id 0 to unlink without deleting or changing the account. Requires the latest profile hash, edit_user on linked accounts, native mapping restrictions and administrator profile policy. dry_run previews without saving.'=>'Связать существующего автора с существующим пользователем WordPress, или используйте user_id 0, чтобы разъединить без удаления или изменения учетной записи. Требуется последний хэш профиля, edit_user для связанных учетных записей, ограничения нативного сопоставления и политика профиля администратора. dry_run предварительно показывает без сохранения.','Delete an unassigned author profile'=>'Удалить не назначенный профиль автора','Delete a verified, unassigned author profile using native taxonomy permissions. Reassign existing posts first. Never deletes its linked WordPress account. Requires the latest profile hash; dry_run checks without deleting.'=>'Удалить проверенный, не назначенный профиль автора с использованием прав нативной таксономии. Сначала переназначьте существующие записи. Никогда не удаляет связанную учетную запись WordPress. Требуется последний хэш профиля; dry_run проверяет без удаления.','The author changed. Read the profile again before saving.'=>'Автор изменился. Прочитайте профиль снова перед сохранением.','You cannot edit the linked user account.'=>'Вы не можете редактировать связанную учетную запись пользователя.','Editing other administrator profiles is disabled.'=>'Редактирование других профилей администратора отключено.','Choose an existing user for a new profile; use link-author-user to remap an existing author.'=>'Выберите существующего пользователя для нового профиля; используйте link-author-user для переназначения существующего автора.','This user already has an author profile.'=>'У этого пользователя уже есть профиль автора.','Choose an editable media attachment for the avatar.'=>'Выберите редактируемую медиавложение для аватара.','Guest author creation requires a name and must be enabled in Authors settings.'=>'Создание гостевого автора требует имени и должно быть включено в настройках авторов.','A linked author uses the WordPress account nicename as its slug.'=>'Связанный автор использует nicename учетной записи WordPress в качестве своего slug.','Choose a unique, non-empty author slug.'=>'Выберите уникальный, непустой slug автора.','Profile field save failed; the original state was restored.'=>'Сохранение поля профиля не удалось; оригинальное состояние было восстановлено.','Profile field save failed and restoration was incomplete. Read the profile before retrying.'=>'Сохранение поля профиля не удалось, и восстановление было неполным. Прочитайте профиль перед повторной попыткой.','The user is already mapped to another author.'=>'Пользователь уже сопоставлен с другим автором.','You cannot delete this author profile.'=>'Вы не можете удалить этот профиль автора.','Reassign posts before deleting this author profile.'=>'Переназначьте записи перед удалением этого профиля автора.','Could not delete the author profile.'=>'Не удалось удалить профиль автора.','The settings could not be saved. Read them again before retrying.'=>'Настройки не удалось сохранить. Прочитайте их снова перед повторной попыткой.','Read Authors settings'=>'Прочитать настройки авторов','Read typed General, Display, Author Pages, Guest Authors and Advanced settings, with defaults and native layout/role/post-type choices. Credentials and license keys are excluded. Whole-module switches use list-features and set-feature-enabled.'=>'Прочитать указанные Общие, Отображение, Страницы авторов, Гостевые авторы и Расширенные настройки, с значениями по умолчанию и нативным выбором макета/роли/типа записи. Учетные данные и лицензионные ключи исключены. Переключатели всего модуля используют list-features и set-feature-enabled.','Update Authors settings'=>'Обновить настройки авторов','Patch only supplied Authors settings; preserves unrelated settings. Use get-plugin-settings for exact fields and native choices. dry_run validates and returns proposed values without saving. Author Pages changes refresh rewrite rules. Pro branding requires Pro.'=>'Обновить только предоставленные настройки авторов; сохраняет несвязанные настройки. Используйте get-plugin-settings для точных полей и нативных выборов. dry_run проверяет и возвращает предлагаемые значения без сохранения. Изменения страниц авторов обновляют правила перезаписи. Профессиональный брендинг требует Pro.','Discover Authors features and actions'=>'Откройте функции и действия авторов','List native Authors screens/modules, enabled state, permissions, edition and read/write workflows. Separate author profiles, post bylines, Author Boxes, Author Lists, Author Categories and Pro Custom Fields. Use field discovery before editing.'=>'Список нативных экранов/модулей авторов, состояние включения, разрешения, редактирование и рабочие процессы чтения/записи. Отдельные профили авторов, строки постов, блоки авторов, списки авторов, категории авторов и профессиональные пользовательские поля. Используйте открытие полей перед редактированием.','Enable or disable an Authors module'=>'Включить или отключить модуль авторов','Change one discovered optional module switch. Autoloaded/core modules cannot be disabled. Does not change individual feature settings or author fields. dry_run previews without saving; refresh the MCP connection after enabling a module.'=>'Измените один найденный переключатель дополнительного модуля. Автозагружаемые/основные модули не могут быть отключены. Не изменяет настройки отдельных функций или поля авторов. dry_run предварительно показывает без сохранения; обновите соединение MCP после включения модуля.','Show Author Box below content'=>'Показать блок автора под содержимым','Show Author Box above content'=>'Показать блок автора над содержимым','Force empty author'=>'Принудительно оставить автора пустым','Username in search field'=>'Имя пользователя в поле поиска','Enable plugin author pages'=>'Включить страницы авторов плагина','Show author pages bio'=>'Показать биографию страниц авторов','Show author post featured image'=>'Показать избранное изображение поста автора','Link author post featured image'=>'Ссылка на избранное изображение поста автора','Show author post excerpt'=>'Показать аннотацию поста автора','Remove single user map restriction'=>'Убрать ограничение на сопоставление одного пользователя','Show author post authors'=>'Показать авторов постов автора','Show author post date'=>'Показать дату публикации автора','Show author post comments'=>'Показать комментарии к публикациям автора','Show author post category'=>'Показать категорию публикации автора','Show author post tags'=>'Показать теги публикации автора','Show author post readmore'=>'Показать кнопку "Читать далее" автора','Hide author pages empty posts message'=>'Скрыть сообщение о пустых публикациях автора','Show author page title'=>'Показать заголовок страницы автора','Disable quick edit author box'=>'Отключить быстрое редактирование блока автора','Enable font awesome'=>'Включить шрифт Font Awesome','Allow guest authors without a user account'=>'Разрешить гостевым авторам без учетной записи пользователя','Author boxes opt out'=>'Отказ от блоков авторов','Allow author multiple categories'=>'Разрешить авторам несколько категорий','Allow guest authors with a user account'=>'Разрешить гостевым авторам с учетной записью пользователя','Show editor author box selection'=>'Показать выбор блока автора в редакторе','Default avatar decorative'=>'Декоративный аватар по умолчанию','Translate author taxonomy'=>'Перевести таксономию автора','Allow administrators to edit other adm